"use strict";
/* The language is the page's: / is English, /fr/ is French (both generated by build_site.py).
   The visitor's choice is remembered; the first visit to / goes to /fr/ for a French browser (inline script in <head>). */
window.LANG = document.documentElement.lang === "fr" ? "fr" : "en";
window.t = (fr, en) => (window.LANG === "fr" ? fr : en);

(() => {
  const nav = document.querySelector(".top nav");
  const box = document.createElement("div");
  box.className = "lang";
  box.setAttribute("role", "group");
  box.setAttribute("aria-label", window.t("Langue", "Language"));
  for (const [l, href] of [["fr", "/fr/"], ["en", "/"]]) {
    const a = document.createElement("a");
    a.textContent = l.toUpperCase();
    a.lang = l;
    a.hreflang = l;
    a.href = href;
    if (l === window.LANG) a.setAttribute("aria-current", "true");
    a.addEventListener("click", () => { try { localStorage.setItem("wodcraft-lang", l); } catch (e) {} });
    box.appendChild(a);
  }
  nav.insertBefore(box, nav.querySelector(".gh"));
})();
